import math, re

def merge_scores(existing, incoming):
    def validate(rows):
        if not isinstance(rows, list): raise ValueError("list required")
        seen=set()
        for row in rows:
            if not isinstance(row,dict) or set(row)!={"id","score"}: raise ValueError("record")
            key,score=row["id"],row["score"]
            if not isinstance(key,str) or not re.fullmatch(r"[a-z][a-z0-9-]*",key) or key in seen: raise ValueError("id")
            if type(score) not in (int,float) or not 0<=score<=4 or not math.isfinite(score): raise ValueError("score")
            seen.add(key)
    validate(existing); validate(incoming)
    result=[dict(row) for row in existing]; positions={row["id"]:i for i,row in enumerate(result)}
    for row in incoming:
        if row["id"] in positions: result[positions[row["id"]]]=dict(row)
        else: positions[row["id"]]=len(result); result.append(dict(row))
    return result
